CREATE TABLE IF NOT EXISTS products (product_id text PRIMARY KEY, persian_title text, brand_name text, category_name text, model text, image_urls jsonb NOT NULL DEFAULT '[]', specs jsonb NOT NULL DEFAULT '[]', search_text text NOT NULL DEFAULT '', search_document tsvector, min_price_toman bigint, max_price_toman bigint, offer_count integer NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS shops (shop_id text PRIMARY KEY, name text, address text, category_names jsonb NOT NULL DEFAULT '[]', instagram text, lat double precision, location_label text, lon double precision, payment_options jsonb NOT NULL DEFAULT '[]', supports_fast_delivery text, website_url text, weekly_hours jsonb NOT NULL DEFAULT '{}', search_text text NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS offers (offer_id text PRIMARY KEY, description text, last_price_changed_at timestamptz, price_toman bigint CHECK(price_toman IS NULL OR price_toman>=0), product_id text NOT NULL REFERENCES products(product_id), seller_title text, shop_id text NOT NULL REFERENCES shops(shop_id), warranty text, search_text text NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS dataset_imports (source text PRIMARY KEY, imported_at timestamptz NOT NULL DEFAULT now(), counts jsonb NOT NULL, archive_sha256 text NOT NULL);
CREATE TABLE IF NOT EXISTS inquiry_records (id text PRIMARY KEY, offer_id text NOT NULL REFERENCES offers(offer_id), status text NOT NULL CHECK(status IN ('available','not_available','unanswered','price_changed')), channel text NOT NULL CHECK(channel IN ('simulation','user_entered')), provenance text NOT NULL CHECK(provenance IN ('simulation','user_reported')), created_at timestamptz NOT NULL, verification_status text NOT NULL CHECK(verification_status IN ('simulated','unknown')), CHECK ((channel='simulation' AND provenance='simulation' AND verification_status='simulated') OR (channel='user_entered' AND provenance='user_reported' AND verification_status='unknown')));

-- Atomic per-day application request budget; contains no message content or credentials.
CREATE TABLE IF NOT EXISTS ai_usage_daily (day text PRIMARY KEY, requests integer NOT NULL DEFAULT 0, prompt_tokens bigint NOT NULL DEFAULT 0, completion_tokens bigint NOT NULL DEFAULT 0);
